import { ImageIcon, PlusIcon } from './Icons';
import { formatPrice, localDesc, localName } from '../utils/format';
import { useI18n } from '../i18n';

export default function ProductCard({ product, onOpenModal, onQuickAdd }) {
  const { lang, t } = useI18n();
  const p = product;
  const available = !!p.is_available;
  const displayName = localName(p, lang);
  const desc = localDesc(p, lang);

  return (
    <article
      className={`product-card${available ? '' : ' unavailable'}`}
      onClick={() => onOpenModal(p)}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => e.key === 'Enter' && onOpenModal(p)}
    >
      {p.image ? (
        <img
          className="product-thumb"
          src={p.image}
          alt={displayName}
          loading="lazy"
          onError={(e) => {
            e.target.style.display = 'none';
            e.target.nextSibling.style.display = 'flex';
          }}
        />
      ) : null}
      <div
        className="product-thumb-placeholder"
        style={p.image ? { display: 'none' } : {}}
      >
        <ImageIcon size={28} />
      </div>

      <div className="product-info">
        <div className="product-name">{displayName}</div>
        {desc ? <div className="product-desc">{desc}</div> : null}
        <div className="product-price-row">
          <span className="product-price">{formatPrice(p.effective_price)}</span>
          {p.discount_price ? (
            <span className="product-price-old">{formatPrice(p.price)}</span>
          ) : null}
          {!available && (
            <span className="unavailable-badge">{t('unavailable')}</span>
          )}
        </div>
      </div>

      <button
        type="button"
        className="product-add-btn"
        disabled={!available}
        onClick={(e) => {
          e.stopPropagation();
          if (!available) return;
          if (onQuickAdd) onQuickAdd(p);
          else onOpenModal(p);
        }}
        aria-label={t('addToCart')}
      >
        <PlusIcon size={16} />
      </button>
    </article>
  );
}

import { ImageIcon, PlusIcon } from './Icons';
import { formatPrice, localDesc, localName } from '../utils/format';
import { useI18n } from '../i18n';

export default function ProductCard({ product, onOpenModal, onQuickAdd }) {
  const { lang, t } = useI18n();
  const p = product;
  const available = !!p.is_available;
  const displayName = localName(p, lang);
  const desc = localDesc(p, lang);

  return (
    <article
      className={`product-card${available ? '' : ' unavailable'}`}
      onClick={() => onOpenModal(p)}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => e.key === 'Enter' && onOpenModal(p)}
    >
      {p.image ? (
        <img
          className="product-thumb"
          src={p.image}
          alt={displayName}
          loading="lazy"
          onError={(e) => {
            e.target.style.display = 'none';
            e.target.nextSibling.style.display = 'flex';
          }}
        />
      ) : null}
      <div
        className="product-thumb-placeholder"
        style={p.image ? { display: 'none' } : {}}
      >
        <ImageIcon size={28} />
      </div>

      <div className="product-info">
        <div className="product-name">{displayName}</div>
        {desc ? <div className="product-desc">{desc}</div> : null}
        <div className="product-price-row">
          <span className="product-price">{formatPrice(p.effective_price)}</span>
          {p.discount_price ? (
            <>
              <span className="product-price-old">{formatPrice(p.price)}</span>
              <span className="product-discount-badge">
                -{Math.round(((p.price - p.discount_price) / p.price) * 100)}%
              </span>
            </>
          ) : null}
          {!available && (
            <span className="unavailable-badge">{t('unavailable')}</span>
          )}
        </div>
      </div>

      <button
        type="button"
        className="product-add-btn"
        disabled={!available}
        onClick={(e) => {
          e.stopPropagation();
          if (!available) return;
          if (onQuickAdd) onQuickAdd(p);
          else onOpenModal(p);
        }}
        aria-label={t('addToCart')}
      >
        <PlusIcon size={16} />
      </button>
    </article>
  );
}

/* ── Design tokens ─────────────────────────────────────────────────── */
:root {
  --primary:      #C0392B;
  --primary-light:#FDECEA;
  --primary-dark: #922B21;
  --bg:           #F5F0EB;
  --card:         #FFFFFF;
  --text:         #1A1A1A;
  --text-sub:     #555555;
  --text-muted:   #999999;
  --border:       #E8E2DB;
  --radius-xl:    20px;
  --radius-lg:    16px;
  --radius-md:    12px;
  --radius-sm:    8px;
  --shadow:       0 2px 12px rgba(0,0,0,0.08);
  --shadow-lg:    0 8px 32px rgba(0,0,0,0.12);
  --transition:   all 0.2s cubic-bezier(0.4,0,0.2,1);
  --nav-h:        64px;
  --bnav-h:       72px;
}
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
body{background:var(--bg);color:var(--text);font-family:-apple-system,'Segoe UI',system-ui,sans-serif;min-height:100vh}
img{display:block;max-width:100%}
button{font-family:inherit;cursor:pointer}

/* ── App / Layout ──────────────────────────────────────────────────── */
.app{min-height:100vh}
.main-content{max-width:860px;margin:0 auto;padding-bottom:calc(var(--bnav-h) + 16px)}
@media(min-width:768px){.main-content{padding-bottom:32px}}

/* ── Header ────────────────────────────────────────────────────────── */
.header{position:sticky;top:0;z-index:100;background:var(--card);border-bottom:1px solid var(--border);height:var(--nav-h)}
.header-inner{display:flex;align-items:center;justify-content:space-between;height:100%;padding:0 16px;max-width:860px;margin:0 auto}
.header-left{display:flex;align-items:center;gap:10px}
.header-logo{width:40px;height:40px;border-radius:50%;overflow:hidden;flex-shrink:0;background:#1a1a1a;display:flex;align-items:center;justify-content:center}
.header-logo img{width:100%;height:100%;object-fit:cover}
.logo-fallback{width:40px;height:40px;background:#1A1A1A;border-radius:50%;display:flex;align-items:center;justify-content:center;color:#fff}
.header-title-wrap{display:flex;flex-direction:column}
.header-name{font-weight:700;font-size:16px;line-height:1.2}
.header-status{font-size:12px;display:flex;align-items:center;gap:4px;margin-top:1px}
.header-status.open{color:#16a34a}
.header-status.closed{color:var(--primary)}
.status-dot{width:7px;height:7px;border-radius:50%;display:inline-block;flex-shrink:0}
.header-status.open .status-dot{background:#16a34a}
.header-status.closed .status-dot{background:var(--primary)}
.header-right{display:flex;align-items:center;gap:6px}
.icon-btn{width:38px;height:38px;border:none;background:transparent;border-radius:50%;display:flex;align-items:center;justify-content:center;color:var(--text);transition:var(--transition)}
.icon-btn:hover{background:var(--bg)}
.lang-btn{padding:5px 11px;border:1px solid var(--border);border-radius:var(--radius-md);background:transparent;font-size:13px;font-weight:600;color:var(--text);transition:var(--transition)}
.lang-btn:hover{background:var(--bg)}
.cart-btn-header{display:none}
@media(min-width:768px){
  .cart-btn-header{display:flex;align-items:center;gap:6px;padding:8px 14px;background:var(--primary);color:#fff;border:none;border-radius:var(--radius-md);font-size:14px;font-weight:500;position:relative;transition:var(--transition)}
  .cart-btn-header:hover{background:var(--primary-dark)}
}
.cart-badge-header{position:absolute;top:-6px;inset-inline-end:-6px;background:#fff;color:var(--primary);font-size:11px;font-weight:700;width:20px;height:20px;border-radius:50%;display:flex;align-items:center;justify-content:center;border:2px solid var(--primary)}

/* ── Slim info bar (status + hours + phone; scroll on small screens) ─ */
.info-bar-wrap{margin:6px 12px 2px;max-height:36px}
.info-bar-scroll{
  display:flex;align-items:center;gap:10px;flex-wrap:nowrap;
  max-height:36px;min-height:32px;padding:0 10px;
  overflow-x:auto;overflow-y:hidden;-webkit-overflow-scrolling:touch;
  background:var(--card);border:1px solid var(--border);border-radius:var(--radius-md);
  scrollbar-width:thin;
}
.info-bar-scroll::-webkit-scrollbar{height:3px}
.info-bar-scroll::-webkit-scrollbar-thumb{background:var(--border);border-radius:3px}
.info-bar-pill{flex-shrink:0;display:inline-flex;align-items:center;gap:4px;white-space:nowrap;font-size:11px;line-height:1.2;font-weight:600}
.info-bar-scroll .open-badge{padding:2px 8px;border-radius:100px}
.info-bar-scroll .open-badge .status-dot{width:6px;height:6px}
.open-badge.open{background:#dcfce7;color:#16a34a}
.open-badge.closed{background:var(--primary-light);color:var(--primary)}
.info-bar-hours{font-weight:500;color:var(--text-muted)}
.info-bar-phone{color:var(--primary);text-decoration:none;font-weight:600}
.info-bar-phone:hover{text-decoration:underline}

/* ── Search Bar ────────────────────────────────────────────────────── */
.search-bar{padding:12px 16px 4px}
.search-input-wrap{position:relative}
.search-icon-wrap{position:absolute;inset-inline-start:14px;top:50%;transform:translateY(-50%);color:var(--text-muted);pointer-events:none;display:flex}
.search-input{width:100%;height:48px;padding-inline-start:44px;padding-inline-end:16px;border:1.5px solid var(--border);border-radius:100px;background:var(--card);font-size:14px;color:var(--text);outline:none;transition:var(--transition);-webkit-appearance:none}
.search-input::placeholder{color:var(--text-muted)}
.search-input:focus{border-color:var(--primary);box-shadow:0 0 0 3px rgba(192,57,43,0.10)}

/* ── Category Chips ────────────────────────────────────────────────── */
.chips-section{padding-bottom:4px}
.chips-scroll{display:flex;gap:8px;overflow-x:auto;padding:8px 16px;scrollbar-width:none}
.chips-scroll::-webkit-scrollbar{display:none}
.chip{white-space:nowrap;flex-shrink:0;padding:8px 18px;border:1.5px solid var(--border);border-radius:100px;background:var(--card);color:var(--text);font-size:13px;font-weight:500;cursor:pointer;transition:var(--transition);display:inline-flex;align-items:center;gap:6px}
.chip:hover{border-color:var(--primary);color:var(--primary)}
.chip.active{background:var(--primary);color:#fff;border-color:var(--primary)}
.chip-thumb{width:18px;height:18px;border-radius:50%;object-fit:cover}
.sub-chip{padding:6px 14px;font-size:12px}

/* ── Section header ────────────────────────────────────────────────── */
.section-header{display:flex;align-items:center;gap:10px;padding:14px 16px 6px}
.section-header h2{font-size:15px;font-weight:700;white-space:nowrap}
.section-header::after{content:'';flex:1;height:1px;background:var(--border)}

/* ── Featured Section ──────────────────────────────────────────────── */
.featured-section{overflow:hidden}
.featured-scroll{display:flex;gap:12px;overflow-x:auto;padding:4px 16px 12px;scrollbar-width:none}
.featured-scroll::-webkit-scrollbar{display:none}
.featured-card{flex-shrink:0;width:140px;background:var(--card);border:none;border-radius:var(--radius-lg);box-shadow:var(--shadow);overflow:hidden;cursor:pointer;transition:var(--transition);text-align:start;padding:0}
.featured-card:hover{transform:translateY(-2px);box-shadow:var(--shadow-lg)}
.featured-card-img{width:100%;height:100px;object-fit:cover}
.featured-card-img-placeholder{width:100%;height:100px;background:#f0ece8;display:flex;align-items:center;justify-content:center;color:var(--text-muted)}
.featured-card-body{padding:8px 10px 10px}
.featured-card-name{font-size:12px;font-weight:600;margin-bottom:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--text)}
.featured-card-price{font-size:12px;font-weight:700;color:var(--primary)}

/* ── Products / Category Groups ────────────────────────────────────── */
.products-section{padding-bottom:16px}
.category-group{margin-bottom:4px}
.products-container{display:flex;flex-direction:column;padding:0 12px;gap:8px}

/* ── Product Card ──────────────────────────────────────────────────── */
.product-card{display:flex;align-items:center;gap:12px;background:var(--card);border-radius:var(--radius-lg);padding:12px;box-shadow:var(--shadow);cursor:pointer;transition:var(--transition);position:relative;border:none;text-align:start;width:100%}
.product-card:hover{box-shadow:var(--shadow-lg)}
.product-card:focus-visible{outline:2px solid var(--primary);outline-offset:2px}
.product-card.unavailable{opacity:.72}
.product-thumb{width:80px;height:80px;border-radius:var(--radius-md);object-fit:cover;flex-shrink:0;background:#f0ece8}
.product-thumb-placeholder{width:80px;height:80px;border-radius:var(--radius-md);background:#f0ece8;display:flex;align-items:center;justify-content:center;color:var(--text-muted);flex-shrink:0}
.product-info{flex:1;min-width:0;padding-inline-end:44px}
.product-name{font-size:14px;font-weight:700;margin-bottom:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--text)}
.product-desc{font-size:12px;color:var(--text-muted);margin-bottom:5px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;line-height:1.4}
.product-price-row{display:flex;align-items:center;gap:6px;flex-wrap:wrap}
.product-price{font-size:14px;font-weight:700;color:var(--primary)}
.product-price-old{font-size:12px;color:var(--text-muted);text-decoration:line-through}
.unavailable-badge{font-size:11px;color:var(--text-muted);background:#f3f4f6;padding:2px 7px;border-radius:100px}
.product-add-btn{position:absolute;inset-inline-end:12px;top:50%;transform:translateY(-50%);width:36px;height:36px;border-radius:50%;border:1.5px solid var(--border);background:#f5f0eb;color:var(--text);display:flex;align-items:center;justify-content:center;transition:var(--transition);z-index:1}
.product-add-btn:hover:not(:disabled){background:var(--primary);border-color:var(--primary);color:#fff}
.product-add-btn:disabled{opacity:.35;cursor:not-allowed}

/* ── Product Modal ──────────────────────────────────────────────────── */
.modal-overlay{position:fixed;inset:0;background:rgba(0,0,0,0.5);backdrop-filter:blur(4px);z-index:200;display:flex;align-items:flex-end;justify-content:center}
@media(min-width:768px){.modal-overlay{align-items:center}}
.product-sheet{width:100%;max-width:500px;background:var(--card);border-radius:var(--radius-xl) var(--radius-xl) 0 0;overflow:hidden;display:flex;flex-direction:column;max-height:92vh}
@media(min-width:768px){.product-sheet{border-radius:var(--radius-xl);max-height:85vh}}
.product-sheet-img-wrap{position:relative;height:220px;background:#f0ece8;flex-shrink:0;overflow:hidden}
.product-sheet-img-wrap img{width:100%;height:100%;object-fit:cover}
.product-sheet-img-placeholder{width:100%;height:100%;display:flex;align-items:center;justify-content:center;color:#ccc}
.product-sheet-close{position:absolute;top:12px;inset-inline-end:12px;width:32px;height:32px;border-radius:50%;background:rgba(255,255,255,0.92);backdrop-filter:blur(4px);border:none;display:flex;align-items:center;justify-content:center;z-index:1;box-shadow:0 1px 6px rgba(0,0,0,.15)}
.product-sheet-body{padding:20px;overflow-y:auto;flex:1}
.product-sheet-title-row{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:10px}
.product-sheet-title{font-size:20px;font-weight:700;flex:1;line-height:1.3}
.product-sheet-price-col{text-align:end;flex-shrink:0}
.product-sheet-price{font-size:20px;font-weight:700;color:var(--primary)}
.product-sheet-old-price{font-size:12px;color:var(--text-muted);text-decoration:line-through;display:block;margin-bottom:2px}
.product-sheet-meta{font-size:13px;color:var(--text-muted);margin-bottom:12px;display:flex;align-items:center;gap:4px}
.product-sheet-desc{font-size:14px;color:var(--text-sub);line-height:1.65;margin-bottom:12px}
.product-sheet-unavail{background:#f3f4f6;border-radius:var(--radius-md);padding:10px 14px;font-size:13px;color:var(--text-muted);text-align:center;margin-bottom:12px}
.product-sheet-footer{padding:16px 20px;padding-bottom:calc(env(safe-area-inset-bottom,0px) + 16px);border-top:1px solid var(--border);display:flex;align-items:center;gap:12px;background:var(--card)}
.qty-control{display:flex;align-items:center;border:1.5px solid var(--border);border-radius:var(--radius-md);overflow:hidden}
.qty-btn{width:38px;height:44px;border:none;background:transparent;display:flex;align-items:center;justify-content:center;color:var(--text);transition:var(--transition)}
.qty-btn:hover:not(:disabled){background:var(--bg)}
.qty-btn:disabled{opacity:.4;cursor:not-allowed}
.qty-value{min-width:36px;text-align:center;font-weight:700;font-size:16px}
.btn-add-sheet{flex:1;height:52px;background:var(--primary);color:#fff;border:none;border-radius:var(--radius-md);font-size:16px;font-weight:600;transition:var(--transition)}
.btn-add-sheet:hover:not(:disabled){background:var(--primary-dark)}
.btn-add-sheet:disabled{background:#e0e0e0;color:var(--text-muted);cursor:not-allowed}

/* ── Cart Drawer ────────────────────────────────────────────────────── */
.cart-overlay{position:fixed;inset:0;background:rgba(0,0,0,0.4);z-index:150}
.cart-drawer{position:fixed;top:0;bottom:0;inset-inline-end:0;width:min(420px,100vw);background:var(--card);box-shadow:var(--shadow-lg);z-index:151;display:flex;flex-direction:column}
.cart-header{display:flex;align-items:center;justify-content:space-between;padding:16px 20px;border-bottom:1px solid var(--border);flex-shrink:0}
.cart-title{font-size:18px;font-weight:700}
.cart-body{flex:1;overflow-y:auto;padding:12px 16px;background:var(--bg)}
.cart-empty{text-align:center;padding:60px 20px;color:var(--text-muted)}
.cart-empty-icon{font-size:48px;display:block;margin-bottom:12px;opacity:.4}
.cart-empty-text{font-size:15px;font-weight:500}
.cart-item{display:flex;align-items:center;gap:10px;background:var(--card);border-radius:var(--radius-md);padding:10px 12px;margin-bottom:8px}
.cart-item-img{width:52px;height:52px;border-radius:var(--radius-sm);object-fit:cover;flex-shrink:0;background:#f0ece8}
.cart-item-img-placeholder{width:52px;height:52px;border-radius:var(--radius-sm);background:#f0ece8;display:flex;align-items:center;justify-content:center;color:var(--text-muted);flex-shrink:0}
.cart-item-info{flex:1;min-width:0}
.cart-item-name{font-size:13px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-bottom:2px}
.cart-item-price{font-size:12px;color:var(--text-muted)}
.cart-item-right{display:flex;flex-direction:column;align-items:flex-end;gap:5px;flex-shrink:0}
.cart-item-total{font-size:13px;font-weight:700;color:var(--primary)}
.cart-item-controls{display:flex;align-items:center;border:1px solid var(--border);border-radius:var(--radius-sm);overflow:hidden}
.cart-qty-btn{width:28px;height:28px;border:none;background:transparent;display:flex;align-items:center;justify-content:center;color:var(--text);transition:var(--transition)}
.cart-qty-btn:hover{background:var(--bg)}
.cart-qty-val{width:26px;text-align:center;font-size:13px;font-weight:600}
.cart-item-delete{background:none;border:none;color:var(--text-muted);display:flex;align-items:center;justify-content:center;padding:2px;transition:var(--transition)}
.cart-item-delete:hover{color:var(--primary)}
.cart-footer{border-top:1px solid var(--border);padding:14px 20px;padding-bottom:calc(env(safe-area-inset-bottom,0px)+14px);background:var(--card);flex-shrink:0}
.cart-subtotal-row{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;font-size:14px}
.cart-subtotal-amount{font-size:20px;font-weight:700}
.btn-checkout{width:100%;height:52px;background:var(--primary);color:#fff;border:none;border-radius:var(--radius-md);font-size:16px;font-weight:600;transition:var(--transition);display:flex;align-items:center;justify-content:center;gap:8px}
.btn-checkout:hover:not(:disabled){background:var(--primary-dark)}
.btn-checkout:disabled{background:#e0e0e0;color:var(--text-muted);cursor:not-allowed}

/* ── Checkout Modal ─────────────────────────────────────────────────── */
.checkout-overlay{position:fixed;inset:0;background:rgba(0,0,0,0.5);backdrop-filter:blur(4px);z-index:200;display:flex;align-items:flex-end;justify-content:center}
@media(min-width:768px){.checkout-overlay{align-items:center}}
.checkout-sheet{width:100%;max-width:560px;background:var(--card);border-radius:var(--radius-xl) var(--radius-xl) 0 0;display:flex;flex-direction:column;max-height:94vh}
@media(min-width:768px){.checkout-sheet{border-radius:var(--radius-xl);max-height:88vh}}
.checkout-header{display:flex;align-items:center;justify-content:space-between;padding:18px 20px;border-bottom:1px solid var(--border);flex-shrink:0}
.checkout-title{font-size:18px;font-weight:700}
.checkout-body{flex:1;overflow-y:auto;padding:20px}
.checkout-footer{padding:14px 20px;padding-bottom:calc(env(safe-area-inset-bottom,0px)+14px);border-top:1px solid var(--border);flex-shrink:0}
.form-group{margin-bottom:14px}
.form-label{display:block;font-size:13px;font-weight:600;color:var(--text-sub);margin-bottom:6px}
.form-input,.form-select,.form-textarea{width:100%;padding:11px 14px;border:1.5px solid var(--border);border-radius:var(--radius-md);font-size:14px;color:var(--text);background:#fff;outline:none;transition:var(--transition);font-family:inherit}
.form-input:focus,.form-select:focus,.form-textarea:focus{border-color:var(--primary);box-shadow:0 0 0 3px rgba(192,57,43,.10)}
.form-input.error,.form-select.error,.form-textarea.error{border-color:var(--primary)}
.form-error{font-size:12px;color:var(--primary);margin-top:4px}
.form-textarea{resize:vertical;min-height:70px}
.address-suggestion-chip{display:block;width:100%;margin-bottom:10px;padding:10px 12px;font-size:13px;line-height:1.4;text-align:start;border:1.5px dashed var(--border);border-radius:var(--radius-md);background:var(--primary-light);color:var(--text);cursor:pointer;transition:var(--transition)}
.address-suggestion-chip:hover{border-color:var(--primary);box-shadow:0 0 0 2px rgba(192,57,43,.08)}
.address-suggestion-chip .address-suggestion-text{font-weight:600;word-break:break-word}
.conditional-section{padding:14px;background:var(--bg);border-radius:var(--radius-md);margin-top:4px;margin-bottom:14px}
.conditional-section .form-group:last-child{margin-bottom:0}
.order-type-btns{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
.order-type-btn{padding:10px;border:1.5px solid var(--border);border-radius:var(--radius-md);background:#fff;font-size:13px;font-weight:500;cursor:pointer;text-align:center;transition:var(--transition);color:var(--text)}
.order-type-btn.active{background:var(--primary);border-color:var(--primary);color:#fff}
.api-error{background:var(--primary-light);color:var(--primary);padding:10px 14px;border-radius:var(--radius-md);font-size:13px;margin-bottom:14px}
.btn-submit{width:100%;height:52px;background:var(--primary);color:#fff;border:none;border-radius:var(--radius-md);font-size:16px;font-weight:600;transition:var(--transition);display:flex;align-items:center;justify-content:center;gap:8px}
.btn-submit:hover:not(:disabled){background:var(--primary-dark)}
.btn-submit:disabled{opacity:.72;cursor:wait}

/* ── Order Success ───────────────────────────────────────────────────── */
.success-overlay{position:fixed;inset:0;background:rgba(0,0,0,0.72);backdrop-filter:blur(8px);z-index:300;display:flex;align-items:center;justify-content:center;padding:20px;animation:fadeIn .3s ease}
@keyframes fadeIn{from{opacity:0}to{opacity:1}}
.success-card{background:var(--card);border-radius:var(--radius-xl);padding:40px 28px;text-align:center;max-width:360px;width:100%;animation:scaleIn .35s cubic-bezier(.34,1.56,.64,1) forwards}
@keyframes scaleIn{from{transform:scale(.85);opacity:0}to{transform:scale(1);opacity:1}}
.success-icon{width:80px;height:80px;background:#dcfce7;border-radius:50%;display:flex;align-items:center;justify-content:center;margin:0 auto 20px;color:#16a34a;animation:popIn .4s .2s ease both}
@keyframes popIn{from{transform:scale(0);opacity:0}to{transform:scale(1);opacity:1}}
.success-title{font-size:22px;font-weight:700;margin-bottom:8px}
.success-message{font-size:15px;color:var(--text-sub);margin-bottom:16px;line-height:1.5}
.success-order-number{font-size:28px;font-weight:800;color:var(--primary);letter-spacing:2px;margin-bottom:28px}
.btn-continue{width:100%;height:50px;background:var(--primary);color:#fff;border:none;border-radius:var(--radius-md);font-size:15px;font-weight:600;transition:var(--transition)}
.btn-continue:hover{background:var(--primary-dark)}

/* ── Bottom Nav ─────────────────────────────────────────────────────── */
.bottom-nav{position:fixed;bottom:0;left:0;right:0;height:var(--bnav-h);background:var(--card);border-top:1px solid var(--border);display:flex;align-items:center;justify-content:space-around;padding:0 16px;padding-bottom:env(safe-area-inset-bottom,0px);z-index:90;box-shadow:0 -2px 12px rgba(0,0,0,.06)}
@media(min-width:768px){.bottom-nav{display:none}}
.bottom-nav-item{display:flex;flex-direction:column;align-items:center;gap:3px;font-size:11px;color:var(--text-muted);background:none;border:none;padding:4px 12px;border-radius:var(--radius-md);transition:var(--transition)}
.bottom-nav-item span{font-weight:500}
.bottom-nav-item.active{color:var(--primary)}
.bottom-nav-cart{display:flex;align-items:center;gap:6px;background:var(--primary);color:#fff;border:none;border-radius:100px;padding:10px 20px;font-size:14px;font-weight:600;min-width:120px;justify-content:center;box-shadow:0 4px 14px rgba(192,57,43,.35);transition:var(--transition)}
.bottom-nav-cart:hover{background:var(--primary-dark)}
.bottom-nav-cart:active{transform:scale(.97)}

/* ── Order history (Profile / orders tab) ─────────────────────────── */
.order-history-section{padding:8px 0 16px}
.order-history-empty{text-align:center;padding:32px 16px;color:var(--text-muted);font-size:15px;line-height:1.5}
.order-history-list{list-style:none;display:flex;flex-direction:column;gap:12px}
.order-history-card{background:var(--card);border:1px solid var(--border);border-radius:var(--radius-lg);padding:14px 16px;box-shadow:var(--shadow)}
.order-history-card-top{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;margin-bottom:8px}
.order-history-number{font-size:14px;font-weight:600;color:var(--text)}
.order-history-meta{font-size:12px;color:var(--text-muted);margin-bottom:8px}
.order-history-total{display:flex;justify-content:space-between;align-items:center;font-size:14px;margin-top:4px}
.order-history-total strong{font-size:17px;color:var(--primary)}
.order-history-error{font-size:13px;color:var(--primary);margin-top:6px}
.order-status-badge{display:inline-block;font-size:11px;font-weight:600;padding:4px 8px;border-radius:var(--radius-sm);white-space:nowrap;max-width:48%;text-overflow:ellipsis;overflow:hidden}
.order-status-badge.status-muted{background:#eee;color:var(--text-muted)}
.order-status-badge.status-pending{background:#fef3c7;color:#92400e}
.order-status-badge.status-progress{background:#dbeafe;color:#1e40af}
.order-status-badge.status-ready{background:#e0e7ff;color:#3730a3}
.order-status-badge.status-success{background:#dcfce7;color:#166534}
.order-status-badge.status-danger{background:#fee2e2;color:#991b1b}

/* ── Utilities ──────────────────────────────────────────────────────── */
.skeleton{background:linear-gradient(90deg,#ede8e3 25%,#e5dfda 50%,#ede8e3 75%);background-size:200% 100%;animation:shimmer 1.4s infinite;border-radius:var(--radius-md)}
.skeleton-card{height:104px;border-radius:var(--radius-lg)}
@keyframes shimmer{0%{background-position:200% 0}100%{background-position:-200% 0}}
.empty-msg{text-align:center;padding:40px 20px;color:var(--text-muted);font-size:15px}
.error-banner{margin:12px;padding:12px 16px;background:var(--primary-light);border-radius:var(--radius-md);color:var(--primary);font-size:14px;display:flex;align-items:center;justify-content:space-between;gap:12px}
.retry-btn{background:var(--primary);color:#fff;border:none;border-radius:var(--radius-sm);padding:6px 14px;font-size:13px;cursor:pointer;transition:var(--transition);flex-shrink:0}
.retry-btn:hover{background:var(--primary-dark)}
.spinner{width:18px;height:18px;border:2px solid rgba(255,255,255,.4);border-top-color:#fff;border-radius:50%;animation:spin .8s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}

/* ── Design tokens ─────────────────────────────────────────────────── */
:root {
  --primary:      #C0392B;
  --primary-light:#FDECEA;
  --primary-dark: #922B21;
  --bg:           #F5F0EB;
  --card:         #FFFFFF;
  --text:         #1A1A1A;
  --text-sub:     #555555;
  --text-muted:   #999999;
  --border:       #E8E2DB;
  --radius-xl:    20px;
  --radius-lg:    16px;
  --radius-md:    12px;
  --radius-sm:    8px;
  --shadow:       0 2px 12px rgba(0,0,0,0.08);
  --shadow-lg:    0 8px 32px rgba(0,0,0,0.12);
  --transition:   all 0.2s cubic-bezier(0.4,0,0.2,1);
  --nav-h:        64px;
  --bnav-h:       72px;
}
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
body{background:var(--bg);color:var(--text);font-family:-apple-system,'Segoe UI',system-ui,sans-serif;min-height:100vh}
img{display:block;max-width:100%}
button{font-family:inherit;cursor:pointer}

/* ── App / Layout ──────────────────────────────────────────────────── */
.app{min-height:100vh}
.main-content{max-width:860px;margin:0 auto;padding-bottom:calc(var(--bnav-h) + 16px)}
@media(min-width:768px){.main-content{padding-bottom:32px}}

/* ── Header ────────────────────────────────────────────────────────── */
.header{position:sticky;top:0;z-index:100;background:var(--card);border-bottom:1px solid var(--border);height:var(--nav-h)}
.header-inner{display:flex;align-items:center;justify-content:space-between;height:100%;padding:0 16px;max-width:860px;margin:0 auto}
.header-left{display:flex;align-items:center;gap:10px}
.header-logo{width:40px;height:40px;border-radius:50%;overflow:hidden;flex-shrink:0;background:#1a1a1a;display:flex;align-items:center;justify-content:center}
.header-logo img{width:100%;height:100%;object-fit:cover}
.logo-fallback{width:40px;height:40px;background:#1A1A1A;border-radius:50%;display:flex;align-items:center;justify-content:center;color:#fff}
.header-title-wrap{display:flex;flex-direction:column}
.header-name{font-weight:700;font-size:16px;line-height:1.2}
.header-status{font-size:12px;display:flex;align-items:center;gap:4px;margin-top:1px}
.header-status.open{color:#16a34a}
.header-status.closed{color:var(--primary)}
.status-dot{width:7px;height:7px;border-radius:50%;display:inline-block;flex-shrink:0}
.header-status.open .status-dot{background:#16a34a}
.header-status.closed .status-dot{background:var(--primary)}
.header-right{display:flex;align-items:center;gap:6px}
.icon-btn{width:38px;height:38px;border:none;background:transparent;border-radius:50%;display:flex;align-items:center;justify-content:center;color:var(--text);transition:var(--transition)}
.icon-btn:hover{background:var(--bg)}
.lang-btn{padding:5px 11px;border:1px solid var(--border);border-radius:var(--radius-md);background:transparent;font-size:13px;font-weight:600;color:var(--text);transition:var(--transition)}
.lang-btn:hover{background:var(--bg)}
.cart-btn-header{display:none}
@media(min-width:768px){
  .cart-btn-header{display:flex;align-items:center;gap:6px;padding:8px 14px;background:var(--primary);color:#fff;border:none;border-radius:var(--radius-md);font-size:14px;font-weight:500;position:relative;transition:var(--transition)}
  .cart-btn-header:hover{background:var(--primary-dark)}
}
.cart-badge-header{position:absolute;top:-6px;inset-inline-end:-6px;background:#fff;color:var(--primary);font-size:11px;font-weight:700;width:20px;height:20px;border-radius:50%;display:flex;align-items:center;justify-content:center;border:2px solid var(--primary)}

/* ── Slim info bar (status + hours + phone; scroll on small screens) ─ */
.info-bar-wrap{margin:6px 12px 2px;max-height:36px}
.info-bar-scroll{
  display:flex;align-items:center;gap:10px;flex-wrap:nowrap;
  max-height:36px;min-height:32px;padding:0 10px;
  overflow-x:auto;overflow-y:hidden;-webkit-overflow-scrolling:touch;
  background:var(--card);border:1px solid var(--border);border-radius:var(--radius-md);
  scrollbar-width:thin;
}
.info-bar-scroll::-webkit-scrollbar{height:3px}
.info-bar-scroll::-webkit-scrollbar-thumb{background:var(--border);border-radius:3px}
.info-bar-pill{flex-shrink:0;display:inline-flex;align-items:center;gap:4px;white-space:nowrap;font-size:11px;line-height:1.2;font-weight:600}
.info-bar-scroll .open-badge{padding:2px 8px;border-radius:100px}
.info-bar-scroll .open-badge .status-dot{width:6px;height:6px}
.open-badge.open{background:#dcfce7;color:#16a34a}
.open-badge.closed{background:var(--primary-light);color:var(--primary)}
.info-bar-hours{font-weight:500;color:var(--text-muted)}
.info-bar-phone{color:var(--primary);text-decoration:none;font-weight:600}
.info-bar-phone:hover{text-decoration:underline}

/* ── Search Bar ────────────────────────────────────────────────────── */
.search-bar{padding:12px 16px 4px}
.search-input-wrap{position:relative}
.search-icon-wrap{position:absolute;inset-inline-start:14px;top:50%;transform:translateY(-50%);color:var(--text-muted);pointer-events:none;display:flex}
.search-input{width:100%;height:48px;padding-inline-start:44px;padding-inline-end:16px;border:1.5px solid var(--border);border-radius:100px;background:var(--card);font-size:14px;color:var(--text);outline:none;transition:var(--transition);-webkit-appearance:none}
.search-input::placeholder{color:var(--text-muted)}
.search-input:focus{border-color:var(--primary);box-shadow:0 0 0 3px rgba(192,57,43,0.10)}

/* ── Category Chips ────────────────────────────────────────────────── */
.chips-section{padding-bottom:4px}
.chips-scroll{display:flex;gap:8px;overflow-x:auto;padding:8px 16px;scrollbar-width:none}
.chips-scroll::-webkit-scrollbar{display:none}
.chip{white-space:nowrap;flex-shrink:0;padding:8px 18px;border:1.5px solid var(--border);border-radius:100px;background:var(--card);color:var(--text);font-size:13px;font-weight:500;cursor:pointer;transition:var(--transition);display:inline-flex;align-items:center;gap:6px}
.chip:hover{border-color:var(--primary);color:var(--primary)}
.chip.active{background:var(--primary);color:#fff;border-color:var(--primary)}
.chip-thumb{width:18px;height:18px;border-radius:50%;object-fit:cover}
.sub-chip{padding:6px 14px;font-size:12px}

/* ── Section header ────────────────────────────────────────────────── */
.section-header{display:flex;align-items:center;gap:10px;padding:14px 16px 6px}
.section-header h2{font-size:15px;font-weight:700;white-space:nowrap}
.section-header::after{content:'';flex:1;height:1px;background:var(--border)}

/* ── Featured Section ──────────────────────────────────────────────── */
.featured-section{overflow:hidden}
.featured-scroll{display:flex;gap:12px;overflow-x:auto;padding:4px 16px 12px;scrollbar-width:none}
.featured-scroll::-webkit-scrollbar{display:none}
.featured-card{flex-shrink:0;width:140px;background:var(--card);border:none;border-radius:var(--radius-lg);box-shadow:var(--shadow);overflow:hidden;cursor:pointer;transition:var(--transition);text-align:start;padding:0}
.featured-card:hover{transform:translateY(-2px);box-shadow:var(--shadow-lg)}
.featured-card-img{width:100%;height:100px;object-fit:cover}
.featured-card-img-placeholder{width:100%;height:100px;background:#f0ece8;display:flex;align-items:center;justify-content:center;color:var(--text-muted)}
.featured-card-body{padding:8px 10px 10px}
.featured-card-name{font-size:12px;font-weight:600;margin-bottom:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--text)}
.featured-card-price{font-size:12px;font-weight:700;color:var(--primary)}

/* ── Products / Category Groups ────────────────────────────────────── */
.products-section{padding-bottom:16px}
.category-group{margin-bottom:4px}
.products-container{display:flex;flex-direction:column;padding:0 12px;gap:8px}

/* ── Product Card ──────────────────────────────────────────────────── */
.product-card{display:flex;align-items:center;gap:12px;background:var(--card);border-radius:var(--radius-lg);padding:12px;box-shadow:var(--shadow);cursor:pointer;transition:var(--transition);position:relative;border:none;text-align:start;width:100%}
.product-card:hover{box-shadow:var(--shadow-lg)}
.product-card:focus-visible{outline:2px solid var(--primary);outline-offset:2px}
.product-card.unavailable{opacity:.72}
.product-thumb{width:80px;height:80px;border-radius:var(--radius-md);object-fit:cover;flex-shrink:0;background:#f0ece8}
.product-thumb-placeholder{width:80px;height:80px;border-radius:var(--radius-md);background:#f0ece8;display:flex;align-items:center;justify-content:center;color:var(--text-muted);flex-shrink:0}
.product-info{flex:1;min-width:0;padding-inline-end:44px}
.product-name{font-size:14px;font-weight:700;margin-bottom:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--text)}
.product-desc{font-size:12px;color:var(--text-muted);margin-bottom:5px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;line-height:1.4}
.product-price-row{display:flex;align-items:center;gap:6px;flex-wrap:wrap}
.product-price{font-size:14px;font-weight:700;color:#16a34a}
.product-price-old{font-size:12px;color:#dc2626;text-decoration:line-through}
.product-discount-badge{font-size:11px;font-weight:700;color:#fff;background:#dc2626;border-radius:4px;padding:1px 5px;line-height:1.4}
.unavailable-badge{font-size:11px;color:var(--text-muted);background:#f3f4f6;padding:2px 7px;border-radius:100px}
.product-add-btn{position:absolute;inset-inline-end:12px;top:50%;transform:translateY(-50%);width:36px;height:36px;border-radius:50%;border:1.5px solid var(--border);background:#f5f0eb;color:var(--text);display:flex;align-items:center;justify-content:center;transition:var(--transition);z-index:1}
.product-add-btn:hover:not(:disabled){background:var(--primary);border-color:var(--primary);color:#fff}
.product-add-btn:disabled{opacity:.35;cursor:not-allowed}

/* ── Product Modal ──────────────────────────────────────────────────── */
.modal-overlay{position:fixed;inset:0;background:rgba(0,0,0,0.5);backdrop-filter:blur(4px);z-index:200;display:flex;align-items:flex-end;justify-content:center}
@media(min-width:768px){.modal-overlay{align-items:center}}
.product-sheet{width:100%;max-width:500px;background:var(--card);border-radius:var(--radius-xl) var(--radius-xl) 0 0;overflow:hidden;display:flex;flex-direction:column;max-height:92vh}
@media(min-width:768px){.product-sheet{border-radius:var(--radius-xl);max-height:85vh}}
.product-sheet-img-wrap{position:relative;height:220px;background:#f0ece8;flex-shrink:0;overflow:hidden}
.product-sheet-img-wrap img{width:100%;height:100%;object-fit:cover}
.product-sheet-img-placeholder{width:100%;height:100%;display:flex;align-items:center;justify-content:center;color:#ccc}
.product-sheet-close{position:absolute;top:12px;inset-inline-end:12px;width:32px;height:32px;border-radius:50%;background:rgba(255,255,255,0.92);backdrop-filter:blur(4px);border:none;display:flex;align-items:center;justify-content:center;z-index:1;box-shadow:0 1px 6px rgba(0,0,0,.15)}
.product-sheet-body{padding:20px;overflow-y:auto;flex:1}
.product-sheet-title-row{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:10px}
.product-sheet-title{font-size:20px;font-weight:700;flex:1;line-height:1.3}
.product-sheet-price-col{text-align:end;flex-shrink:0}
.product-sheet-price{font-size:20px;font-weight:700;color:var(--primary)}
.product-sheet-old-price{font-size:12px;color:var(--text-muted);text-decoration:line-through;display:block;margin-bottom:2px}
.product-sheet-meta{font-size:13px;color:var(--text-muted);margin-bottom:12px;display:flex;align-items:center;gap:4px}
.product-sheet-desc{font-size:14px;color:var(--text-sub);line-height:1.65;margin-bottom:12px}
.product-sheet-unavail{background:#f3f4f6;border-radius:var(--radius-md);padding:10px 14px;font-size:13px;color:var(--text-muted);text-align:center;margin-bottom:12px}
.product-sheet-footer{padding:16px 20px;padding-bottom:calc(env(safe-area-inset-bottom,0px) + 16px);border-top:1px solid var(--border);display:flex;align-items:center;gap:12px;background:var(--card)}
.qty-control{display:flex;align-items:center;border:1.5px solid var(--border);border-radius:var(--radius-md);overflow:hidden}
.qty-btn{width:38px;height:44px;border:none;background:transparent;display:flex;align-items:center;justify-content:center;color:var(--text);transition:var(--transition)}
.qty-btn:hover:not(:disabled){background:var(--bg)}
.qty-btn:disabled{opacity:.4;cursor:not-allowed}
.qty-value{min-width:36px;text-align:center;font-weight:700;font-size:16px}
.btn-add-sheet{flex:1;height:52px;background:var(--primary);color:#fff;border:none;border-radius:var(--radius-md);font-size:16px;font-weight:600;transition:var(--transition)}
.btn-add-sheet:hover:not(:disabled){background:var(--primary-dark)}
.btn-add-sheet:disabled{background:#e0e0e0;color:var(--text-muted);cursor:not-allowed}

/* ── Cart Drawer ────────────────────────────────────────────────────── */
.cart-overlay{position:fixed;inset:0;background:rgba(0,0,0,0.4);z-index:150}
.cart-drawer{position:fixed;top:0;bottom:0;inset-inline-end:0;width:min(420px,100vw);background:var(--card);box-shadow:var(--shadow-lg);z-index:151;display:flex;flex-direction:column}
.cart-header{display:flex;align-items:center;justify-content:space-between;padding:16px 20px;border-bottom:1px solid var(--border);flex-shrink:0}
.cart-title{font-size:18px;font-weight:700}
.cart-body{flex:1;overflow-y:auto;padding:12px 16px;background:var(--bg)}
.cart-empty{text-align:center;padding:60px 20px;color:var(--text-muted)}
.cart-empty-icon{font-size:48px;display:block;margin-bottom:12px;opacity:.4}
.cart-empty-text{font-size:15px;font-weight:500}
.cart-item{display:flex;align-items:center;gap:10px;background:var(--card);border-radius:var(--radius-md);padding:10px 12px;margin-bottom:8px}
.cart-item-img{width:52px;height:52px;border-radius:var(--radius-sm);object-fit:cover;flex-shrink:0;background:#f0ece8}
.cart-item-img-placeholder{width:52px;height:52px;border-radius:var(--radius-sm);background:#f0ece8;display:flex;align-items:center;justify-content:center;color:var(--text-muted);flex-shrink:0}
.cart-item-info{flex:1;min-width:0}
.cart-item-name{font-size:13px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-bottom:2px}
.cart-item-price{font-size:12px;color:var(--text-muted)}
.cart-item-right{display:flex;flex-direction:column;align-items:flex-end;gap:5px;flex-shrink:0}
.cart-item-total{font-size:13px;font-weight:700;color:var(--primary)}
.cart-item-controls{display:flex;align-items:center;border:1px solid var(--border);border-radius:var(--radius-sm);overflow:hidden}
.cart-qty-btn{width:28px;height:28px;border:none;background:transparent;display:flex;align-items:center;justify-content:center;color:var(--text);transition:var(--transition)}
.cart-qty-btn:hover{background:var(--bg)}
.cart-qty-val{width:26px;text-align:center;font-size:13px;font-weight:600}
.cart-item-delete{background:none;border:none;color:var(--text-muted);display:flex;align-items:center;justify-content:center;padding:2px;transition:var(--transition)}
.cart-item-delete:hover{color:var(--primary)}
.cart-footer{border-top:1px solid var(--border);padding:14px 20px;padding-bottom:calc(env(safe-area-inset-bottom,0px)+14px);background:var(--card);flex-shrink:0}
.cart-subtotal-row{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;font-size:14px}
.cart-subtotal-amount{font-size:20px;font-weight:700}
.btn-checkout{width:100%;height:52px;background:var(--primary);color:#fff;border:none;border-radius:var(--radius-md);font-size:16px;font-weight:600;transition:var(--transition);display:flex;align-items:center;justify-content:center;gap:8px}
.btn-checkout:hover:not(:disabled){background:var(--primary-dark)}
.btn-checkout:disabled{background:#e0e0e0;color:var(--text-muted);cursor:not-allowed}

/* ── Checkout Modal ─────────────────────────────────────────────────── */
.checkout-overlay{position:fixed;inset:0;background:rgba(0,0,0,0.5);backdrop-filter:blur(4px);z-index:200;display:flex;align-items:flex-end;justify-content:center}
@media(min-width:768px){.checkout-overlay{align-items:center}}
.checkout-sheet{width:100%;max-width:560px;background:var(--card);border-radius:var(--radius-xl) var(--radius-xl) 0 0;display:flex;flex-direction:column;max-height:94vh}
@media(min-width:768px){.checkout-sheet{border-radius:var(--radius-xl);max-height:88vh}}
.checkout-header{display:flex;align-items:center;justify-content:space-between;padding:18px 20px;border-bottom:1px solid var(--border);flex-shrink:0}
.checkout-title{font-size:18px;font-weight:700}
.checkout-body{flex:1;overflow-y:auto;padding:20px}
.checkout-footer{padding:14px 20px;padding-bottom:calc(env(safe-area-inset-bottom,0px)+14px);border-top:1px solid var(--border);flex-shrink:0}
.form-group{margin-bottom:14px}
.form-label{display:block;font-size:13px;font-weight:600;color:var(--text-sub);margin-bottom:6px}
.form-input,.form-select,.form-textarea{width:100%;padding:11px 14px;border:1.5px solid var(--border);border-radius:var(--radius-md);font-size:14px;color:var(--text);background:#fff;outline:none;transition:var(--transition);font-family:inherit}
.form-input:focus,.form-select:focus,.form-textarea:focus{border-color:var(--primary);box-shadow:0 0 0 3px rgba(192,57,43,.10)}
.form-input.error,.form-select.error,.form-textarea.error{border-color:var(--primary)}
.form-error{font-size:12px;color:var(--primary);margin-top:4px}
.form-textarea{resize:vertical;min-height:70px}
.address-suggestion-chip{display:block;width:100%;margin-bottom:10px;padding:10px 12px;font-size:13px;line-height:1.4;text-align:start;border:1.5px dashed var(--border);border-radius:var(--radius-md);background:var(--primary-light);color:var(--text);cursor:pointer;transition:var(--transition)}
.address-suggestion-chip:hover{border-color:var(--primary);box-shadow:0 0 0 2px rgba(192,57,43,.08)}
.address-suggestion-chip .address-suggestion-text{font-weight:600;word-break:break-word}
.conditional-section{padding:14px;background:var(--bg);border-radius:var(--radius-md);margin-top:4px;margin-bottom:14px}
.conditional-section .form-group:last-child{margin-bottom:0}
.order-type-btns{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
.order-type-btn{padding:10px;border:1.5px solid var(--border);border-radius:var(--radius-md);background:#fff;font-size:13px;font-weight:500;cursor:pointer;text-align:center;transition:var(--transition);color:var(--text)}
.order-type-btn.active{background:var(--primary);border-color:var(--primary);color:#fff}
.api-error{background:var(--primary-light);color:var(--primary);padding:10px 14px;border-radius:var(--radius-md);font-size:13px;margin-bottom:14px}
.btn-submit{width:100%;height:52px;background:var(--primary);color:#fff;border:none;border-radius:var(--radius-md);font-size:16px;font-weight:600;transition:var(--transition);display:flex;align-items:center;justify-content:center;gap:8px}
.btn-submit:hover:not(:disabled){background:var(--primary-dark)}
.btn-submit:disabled{opacity:.72;cursor:wait}

/* ── Order Success ───────────────────────────────────────────────────── */
.success-overlay{position:fixed;inset:0;background:rgba(0,0,0,0.72);backdrop-filter:blur(8px);z-index:300;display:flex;align-items:center;justify-content:center;padding:20px;animation:fadeIn .3s ease}
@keyframes fadeIn{from{opacity:0}to{opacity:1}}
.success-card{background:var(--card);border-radius:var(--radius-xl);padding:40px 28px;text-align:center;max-width:360px;width:100%;animation:scaleIn .35s cubic-bezier(.34,1.56,.64,1) forwards}
@keyframes scaleIn{from{transform:scale(.85);opacity:0}to{transform:scale(1);opacity:1}}
.success-icon{width:80px;height:80px;background:#dcfce7;border-radius:50%;display:flex;align-items:center;justify-content:center;margin:0 auto 20px;color:#16a34a;animation:popIn .4s .2s ease both}
@keyframes popIn{from{transform:scale(0);opacity:0}to{transform:scale(1);opacity:1}}
.success-title{font-size:22px;font-weight:700;margin-bottom:8px}
.success-message{font-size:15px;color:var(--text-sub);margin-bottom:16px;line-height:1.5}
.success-order-number{font-size:28px;font-weight:800;color:var(--primary);letter-spacing:2px;margin-bottom:28px}
.btn-continue{width:100%;height:50px;background:var(--primary);color:#fff;border:none;border-radius:var(--radius-md);font-size:15px;font-weight:600;transition:var(--transition)}
.btn-continue:hover{background:var(--primary-dark)}

/* ── Bottom Nav ─────────────────────────────────────────────────────── */
.bottom-nav{position:fixed;bottom:0;left:0;right:0;height:var(--bnav-h);background:var(--card);border-top:1px solid var(--border);display:flex;align-items:center;justify-content:space-around;padding:0 16px;padding-bottom:env(safe-area-inset-bottom,0px);z-index:90;box-shadow:0 -2px 12px rgba(0,0,0,.06)}
@media(min-width:768px){.bottom-nav{display:none}}
.bottom-nav-item{display:flex;flex-direction:column;align-items:center;gap:3px;font-size:11px;color:var(--text-muted);background:none;border:none;padding:4px 12px;border-radius:var(--radius-md);transition:var(--transition)}
.bottom-nav-item span{font-weight:500}
.bottom-nav-item.active{color:var(--primary)}
.bottom-nav-cart{display:flex;align-items:center;gap:6px;background:var(--primary);color:#fff;border:none;border-radius:100px;padding:10px 20px;font-size:14px;font-weight:600;min-width:120px;justify-content:center;box-shadow:0 4px 14px rgba(192,57,43,.35);transition:var(--transition)}
.bottom-nav-cart:hover{background:var(--primary-dark)}
.bottom-nav-cart:active{transform:scale(.97)}

/* ── Order history (Profile / orders tab) ─────────────────────────── */
.order-history-section{padding:8px 0 16px}
.order-history-empty{text-align:center;padding:32px 16px;color:var(--text-muted);font-size:15px;line-height:1.5}
.order-history-list{list-style:none;display:flex;flex-direction:column;gap:12px}
.order-history-card{background:var(--card);border:1px solid var(--border);border-radius:var(--radius-lg);padding:14px 16px;box-shadow:var(--shadow)}
.order-history-card-top{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;margin-bottom:8px}
.order-history-number{font-size:14px;font-weight:600;color:var(--text)}
.order-history-meta{font-size:12px;color:var(--text-muted);margin-bottom:8px}
.order-history-total{display:flex;justify-content:space-between;align-items:center;font-size:14px;margin-top:4px}
.order-history-total strong{font-size:17px;color:var(--primary)}
.order-history-error{font-size:13px;color:var(--primary);margin-top:6px}
.order-status-badge{display:inline-block;font-size:11px;font-weight:600;padding:4px 8px;border-radius:var(--radius-sm);white-space:nowrap;max-width:48%;text-overflow:ellipsis;overflow:hidden}
.order-status-badge.status-muted{background:#eee;color:var(--text-muted)}
.order-status-badge.status-pending{background:#fef3c7;color:#92400e}
.order-status-badge.status-progress{background:#dbeafe;color:#1e40af}
.order-status-badge.status-ready{background:#e0e7ff;color:#3730a3}
.order-status-badge.status-success{background:#dcfce7;color:#166534}
.order-status-badge.status-danger{background:#fee2e2;color:#991b1b}

/* ── Utilities ──────────────────────────────────────────────────────── */
.skeleton{background:linear-gradient(90deg,#ede8e3 25%,#e5dfda 50%,#ede8e3 75%);background-size:200% 100%;animation:shimmer 1.4s infinite;border-radius:var(--radius-md)}
.skeleton-card{height:104px;border-radius:var(--radius-lg)}
@keyframes shimmer{0%{background-position:200% 0}100%{background-position:-200% 0}}
.empty-msg{text-align:center;padding:40px 20px;color:var(--text-muted);font-size:15px}
.error-banner{margin:12px;padding:12px 16px;background:var(--primary-light);border-radius:var(--radius-md);color:var(--primary);font-size:14px;display:flex;align-items:center;justify-content:space-between;gap:12px}
.retry-btn{background:var(--primary);color:#fff;border:none;border-radius:var(--radius-sm);padding:6px 14px;font-size:13px;cursor:pointer;transition:var(--transition);flex-shrink:0}
.retry-btn:hover{background:var(--primary-dark)}
.spinner{width:18px;height:18px;border:2px solid rgba(255,255,255,.4);border-top-color:#fff;border-radius:50%;animation:spin .8s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
